content.css:
html,
body {
  margin: 0;
  padding: 0;
  overflow: hidden;
  font-family: "Segoe UI", wf_standard-font, -apple-system, BlinkMacSystemFont, sans-serif;
  -webkit-font-smoothing: antialiased;
}
.cv-empty {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
  color: #8C9197;
  font-size: 11px;
}
.sf {
  position: relative;
  display: flex;
  flex-direction: column;
  width: 100%;
  height: 100%;
  box-sizing: border-box;
  background: var(--bg);
  color: var(--ink);
  font-family: "Segoe UI", "Inter", wf_standard-font, system-ui, -apple-system, sans-serif;
  font-size: var(--fs);
  overflow: hidden;
}
.sf.sf-border {
  border: 1px solid var(--line);
  border-radius: calc(6px * var(--ui, 1));
}
.sf *,
.sf *::before,
.sf *::after {
  box-sizing: border-box;
}
.sf button {
  font: inherit;
  color: inherit;
  background: none;
  border: 0;
  margin: 0;
  padding: 0;
  cursor: pointer;
}
.sf button:focus-visible,
.sf input:focus-visible,
.sf a:focus-visible,
.sf .sf-scroll:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: -2px;
}
.sf .sf-ico {
  flex: none;
  display: block;
}
.sf-toolbar {
  flex: none;
  display: flex;
  align-items: center;
  gap: calc(8px * var(--ui, 1));
  min-height: calc(38px * var(--ui, 1));
  padding: calc(6px * var(--ui, 1)) calc(6px * var(--ui, 1)) calc(6px * var(--ui, 1)) 2px;
}
.sf-search {
  flex: 0 1 calc(220px * var(--ui, 1));
  min-width: calc(120px * var(--ui, 1));
  display: flex;
  align-items: center;
  gap: calc(6px * var(--ui, 1));
  height: calc(28px * var(--ui, 1));
  padding: 0 calc(10px * var(--ui, 1));
  border: 1px solid var(--line);
  border-radius: 999px;
  background: var(--bg);
  color: var(--muted);
  transition: border-color 0.15s, box-shadow 0.15s;
}
.sf-search:focus-within {
  border-color: var(--accent);
  box-shadow: 0 0 0 calc(3px * var(--ui, 1)) var(--accent-soft);
  color: var(--accent);
}
.sf-search input {
  flex: 1;
  min-width: 0;
  border: 0;
  outline: none;
  background: transparent;
  color: var(--ink);
  font: inherit;
  font-size: calc(12px * var(--ui, 1));
}
.sf-search input::placeholder {
  color: var(--muted);
}
.sf-chips {
  flex: 1 1 auto;
  display: flex;
  align-items: center;
  gap: calc(6px * var(--ui, 1));
  min-width: 0;
  overflow-x: auto;
  scrollbar-width: none;
}
.sf-chips::-webkit-scrollbar {
  display: none;
}
.sf-chip {
  flex: none;
  display: inline-flex;
  align-items: center;
  gap: calc(6px * var(--ui, 1));
  height: calc(26px * var(--ui, 1));
  max-width: calc(280px * var(--ui, 1));
  padding: 0 calc(6px * var(--ui, 1)) 0 calc(10px * var(--ui, 1));
  border-radius: 999px;
  font-size: calc(11.5px * var(--ui, 1));
  white-space: nowrap;
  background: var(--accent-soft);
  color: var(--ink);
  border: 1px solid transparent;
}
.sf-chip .sf-scope {
  color: var(--accent);
}
.sf-chip .sf-chip-name {
  font-weight: 600;
}
.sf-chip .sf-chip-val {
  overflow: hidden;
  text-overflow: ellipsis;
  color: var(--soft);
}
.sf-chip.is-local {
  background: transparent;
  border: 1px dashed var(--muted);
}
.sf-chip.is-local .sf-scope {
  color: var(--muted);
}
.sf-chip:hover {
  border-color: var(--accent);
}
.sf-chip-x {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: calc(18px * var(--ui, 1));
  height: calc(18px * var(--ui, 1));
  border-radius: 999px;
  color: var(--muted);
  cursor: pointer;
}
.sf-chip-x:hover {
  background: var(--neg-soft);
  color: var(--neg);
}
.sf-actions {
  flex: none;
  display: flex;
  align-items: center;
  gap: 2px;
  margin-left: auto;
}
.sf-act {
  display: inline-flex;
  align-items: center;
  gap: calc(5px * var(--ui, 1));
  height: calc(28px * var(--ui, 1));
  min-width: calc(28px * var(--ui, 1));
  justify-content: center;
  border-radius: calc(6px * var(--ui, 1));
  color: var(--soft);
  font-size: calc(11.5px * var(--ui, 1));
}
.sf-act.has-text {
  padding: 0 calc(8px * var(--ui, 1));
  color: var(--neg);
}
.sf-act:hover {
  background: var(--hover);
  color: var(--ink);
}
.sf-act.is-on {
  background: var(--accent-soft);
  color: var(--accent);
}
.sf-scroll {
  position: relative;
  flex: 1 1 auto;
  min-height: 0;
  overflow: auto;
  border-top: 1px solid var(--line);
  scrollbar-width: thin;
  scrollbar-color: var(--line) transparent;
}
.sf-scroll::-webkit-scrollbar {
  width: calc(10px * var(--ui, 1));
  height: calc(10px * var(--ui, 1));
}
.sf-scroll::-webkit-scrollbar-thumb {
  background: var(--line);
  border-radius: calc(10px * var(--ui, 1));
  border: 2px solid var(--bg);
}
.sf-table {
  table-layout: fixed;
  border-collapse: separate;
  border-spacing: 0;
  font-variant-numeric: tabular-nums;
}
.sf-th,
.sf-fth,
.sf-td {
  padding: 0 calc(10px * var(--ui, 1));
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  text-align: left;
  box-shadow: inset 0 -1px 0 var(--rl), inset -1px 0 0 var(--cl);
}
.sf-right {
  text-align: right;
}
.sf-center {
  text-align: center;
}
.sf-th {
  position: sticky;
  top: 0;
  z-index: 3;
  height: calc(38px * var(--ui, 1));
  padding: 0 calc(4px * var(--ui, 1)) 0 calc(10px * var(--ui, 1));
  background: var(--head);
  color: var(--head-ink);
  font-size: var(--hfs);
  font-weight: var(--hweight);
  white-space: var(--hwrap);
  vertical-align: bottom;
  user-select: none;
  box-shadow: inset 0 -1px 0 var(--line), inset -1px 0 0 var(--cl);
}
.sf-th.sf-right .sf-th-label {
  justify-content: flex-end;
  text-align: right;
}
.sf-th.sf-dragging {
  opacity: 0.45;
}
.sf-th.sf-drop {
  box-shadow: inset calc(3px * var(--ui, 1)) 0 0 var(--accent), inset 0 -1px 0 var(--line);
}
.sf-th:hover .sf-th-menu {
  opacity: 1;
}
.sf-th-in {
  display: flex;
  align-items: flex-end;
  gap: 2px;
  padding-bottom: calc(6px * var(--ui, 1));
}
.sf-th-label {
  flex: 1 1 auto;
  min-width: 0;
  display: flex;
  align-items: center;
  gap: calc(4px * var(--ui, 1));
  text-align: left;
  font-weight: inherit !important;
  white-space: inherit;
}
.sf-th-label .sf-th-text {
  overflow: hidden;
  text-overflow: ellipsis;
  line-height: 1.25;
}
.sf-th-label .sf-sorted {
  color: var(--accent);
}
.sf-th-menu {
  flex: none;
  width: calc(20px * var(--ui, 1));
  height: calc(20px * var(--ui, 1));
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: calc(4px * var(--ui, 1));
  color: var(--muted);
  opacity: 0.35;
}
.sf-th-menu:hover,
.sf-th-menu:focus-visible {
  opacity: 1;
  background: var(--hover);
  color: var(--ink);
}
.sf-grip {
  position: absolute;
  top: 0;
  right: 0;
  width: calc(7px * var(--ui, 1));
  height: 100%;
  cursor: col-resize;
}
.sf-grip:hover {
  background: linear-gradient(90deg, transparent calc(3px * var(--ui, 1)), var(--accent) calc(3px * var(--ui, 1)), var(--accent) calc(5px * var(--ui, 1)), transparent calc(5px * var(--ui, 1)));
}
.sf-fth {
  position: sticky;
  z-index: 3;
  height: calc(34px * var(--ui, 1));
  padding: calc(4px * var(--ui, 1)) calc(5px * var(--ui, 1)) calc(5px * var(--ui, 1));
  background: var(--head);
  box-shadow: inset 0 -1px 0 var(--line), inset -1px 0 0 var(--cl);
  font-weight: 400;
}
.sf-fbtn {
  display: flex;
  align-items: center;
  gap: calc(5px * var(--ui, 1));
  width: 100%;
  height: calc(24px * var(--ui, 1));
  padding: 0 calc(6px * var(--ui, 1)) 0 calc(7px * var(--ui, 1));
  border: 1px solid var(--line);
  border-radius: calc(5px * var(--ui, 1));
  background: var(--bg);
  color: var(--muted);
  font-size: calc(11px * var(--ui, 1));
  text-align: left;
  transition: border-color 0.15s, background 0.15s;
}
.sf-fbtn .sf-fbtn-text {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.sf-fbtn:hover {
  border-color: var(--accent);
  color: var(--ink);
}
.sf-fbtn.is-local {
  border-style: dashed;
}
.sf-fbtn.is-on {
  border-color: var(--accent);
  border-style: solid;
  background: var(--accent-soft);
  color: var(--ink);
  font-weight: 600;
}
.sf-fbtn.is-on > .sf-ico {
  color: var(--accent);
}
.sf-fbtn .sf-chip-x {
  width: calc(16px * var(--ui, 1));
  height: calc(16px * var(--ui, 1));
}
.sf-td {
  position: relative;
  height: var(--rowh);
  background: var(--bg);
  color: var(--ink);
}
.sf-tr {
  cursor: default;
}
.sf-tr.sf-band > .sf-td {
  background: var(--band);
}
.sf-tr:hover > .sf-td {
  background: var(--hover);
}
.sf-tr.sf-sel > .sf-td {
  background: var(--sel);
}
.sf-tr.sf-sel > .sf-td:first-child {
  box-shadow: inset calc(3px * var(--ui, 1)) 0 0 var(--accent), inset 0 -1px 0 var(--rl);
}
.sf-tr.sf-focus > .sf-td {
  box-shadow: inset 0 1px 0 var(--accent), inset 0 -1px 0 var(--accent);
}
.sf-v {
  position: relative;
  z-index: 1;
}
.sf-v.is-blank::before {
  content: "\2013";
  color: var(--muted);
}
.sf-link {
  color: var(--accent);
  text-decoration: underline;
  text-underline-offset: 2px;
  cursor: pointer;
}
.sf-bar {
  position: absolute;
  left: calc(4px * var(--ui, 1));
  top: 24%;
  bottom: 24%;
  max-width: calc(100% - calc(8px * var(--ui, 1)));
  border-radius: calc(3px * var(--ui, 1));
  background: var(--mark);
  opacity: 0.32;
}
.sf-bar.is-neg {
  background: var(--neg);
}
.sf-good {
  color: var(--pos) !important;
  font-weight: 600;
}
.sf-good::after,
.sf-bad::after {
  content: "";
  position: absolute;
  inset: calc(3px * var(--ui, 1)) 2px;
  border-radius: calc(4px * var(--ui, 1));
  z-index: 0;
}
.sf-good::after {
  background: var(--pos-soft);
}
.sf-bad {
  color: var(--neg) !important;
  font-weight: 600;
}
.sf-bad::after {
  background: var(--neg-soft);
}
.sf-cell-ico {
  display: inline-block;
  margin-right: calc(4px * var(--ui, 1));
  vertical-align: -0.12em;
}
.sf-cell-ico.is-good {
  color: var(--pos);
}
.sf-cell-ico.is-mid {
  color: var(--muted);
}
.sf-cell-ico.is-bad {
  color: var(--neg);
}
.sf-dot {
  display: inline-block;
  width: calc(8px * var(--ui, 1));
  height: calc(8px * var(--ui, 1));
  margin-right: calc(6px * var(--ui, 1));
  border-radius: 999px;
  vertical-align: 0.04em;
}
.sf-dot.is-good {
  background: var(--pos);
}
.sf-dot.is-mid {
  background: var(--warn);
}
.sf-dot.is-bad {
  background: var(--neg);
}
.sf-tinted {
  font-weight: 600;
}
.sf-td.sf-filled {
  background: var(--cell) !important;
}
.sf-pill {
  display: inline-block;
  padding: 0 calc(8px * var(--ui, 1));
  border-radius: 999px;
  line-height: 1.65;
  color: var(--cell);
  background: color-mix(in srgb, var(--cell) 14%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--cell) 38%, transparent);
  font-weight: 600;
}
.sf-approx::before {
  content: "\2248\00A0";
  color: var(--muted);
  font-weight: 400;
}
.sf-fth.is-none {
  cursor: default;
}
.sf-frz {
  position: sticky;
  z-index: 2;
}
.sf-th.sf-frz,
.sf-fth.sf-frz {
  z-index: 5;
}
.sf-frz-last {
  box-shadow: inset 0 -1px 0 var(--rl), inset -1px 0 0 var(--line), calc(6px * var(--ui, 1)) 0 calc(8px * var(--ui, 1)) calc(-6px * var(--ui, 1)) var(--shadow) !important;
}
.sf-grp {
  cursor: pointer;
}
.sf-grp > .sf-td {
  background: var(--head);
  font-weight: 600;
  box-shadow: inset 0 -1px 0 var(--line);
}
.sf-grp:hover > .sf-td {
  background: var(--hover);
}
.sf-grp-label {
  display: inline-flex;
  align-items: center;
  gap: calc(6px * var(--ui, 1));
}
.sf-grp-label .sf-ico {
  color: var(--accent);
}
.sf-grp-count {
  padding: 1px calc(7px * var(--ui, 1));
  border-radius: 999px;
  background: var(--accent-soft);
  color: var(--accent);
  font-size: calc(10.5px * var(--ui, 1));
  font-weight: 600;
}
.sf-total > .sf-td {
  position: sticky;
  bottom: 0;
  z-index: 3;
  height: calc(var(--rowh) + 2px);
  background: var(--head);
  color: var(--head-ink);
  font-weight: 700;
  box-shadow: inset 0 2px 0 var(--ink);
}
.sf-total > .sf-td.sf-frz {
  z-index: 5;
}
.sf-spacer-cell {
  padding: 0;
  border: 0;
  box-shadow: none;
}
.sf-norows {
  padding: calc(28px * var(--ui, 1)) calc(12px * var(--ui, 1));
  color: var(--muted);
  text-align: left;
}
.sf-status {
  flex: none;
  display: flex;
  align-items: center;
  gap: calc(10px * var(--ui, 1));
  min-height: calc(28px * var(--ui, 1));
  padding: calc(4px * var(--ui, 1)) calc(4px * var(--ui, 1)) 0 2px;
  border-top: 1px solid var(--line);
  color: var(--soft);
  font-size: calc(11px * var(--ui, 1));
  white-space: nowrap;
}
.sf-status b {
  color: var(--ink);
  font-weight: 700;
}
.sf-status-left {
  flex: none;
}
.sf-status-mid {
  flex: 1 1 auto;
  display: flex;
  gap: calc(6px * var(--ui, 1));
  min-width: 0;
  overflow: hidden;
}
.sf-status-right {
  flex: none;
  display: flex;
  align-items: center;
  gap: calc(4px * var(--ui, 1));
}
.sf-muted {
  color: var(--muted);
}
.sf-dot-sep {
  margin: 0 calc(6px * var(--ui, 1));
  color: var(--muted);
}
.sf-page {
  min-width: calc(40px * var(--ui, 1));
  text-align: center;
}
.sf-flip .sf-ico {
  transform: scaleX(-1);
}
.sf-badge {
  display: inline-flex;
  align-items: center;
  gap: calc(5px * var(--ui, 1));
  height: calc(20px * var(--ui, 1));
  padding: 0 calc(8px * var(--ui, 1));
  border-radius: 999px;
  font-size: calc(10.5px * var(--ui, 1));
}
.sf-badge.is-report {
  background: var(--accent-soft);
  color: var(--accent);
  font-weight: 600;
}
.sf-badge.is-local {
  border: 1px dashed var(--muted);
  color: var(--soft);
}
.sf-sr {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
}
.sf-layer {
  position: absolute;
  inset: 0;
  z-index: 20;
  pointer-events: none;
}
.sf-layer.open > * {
  pointer-events: auto;
}
.sf-pop {
  position: absolute;
  width: calc(272px * var(--ui, 1));
  display: flex;
  flex-direction: column;
  background: var(--pop);
  color: var(--ink);
  border: 1px solid var(--line);
  border-radius: calc(10px * var(--ui, 1));
  box-shadow: 0 calc(12px * var(--ui, 1)) calc(32px * var(--ui, 1)) calc(-8px * var(--ui, 1)) var(--shadow), 0 2px calc(6px * var(--ui, 1)) var(--shadow);
  font-size: calc(12px * var(--ui, 1));
  overflow: hidden;
  animation: sf-in 0.12s ease-out;
}
@keyframes sf-in {
  from {
    opacity: 0;
    transform: translateY(calc(-3px * var(--ui, 1)));
  }
  to {
    opacity: 1;
    transform: none;
  }
}
.sf-pop-head {
  flex: none;
  display: flex;
  align-items: center;
  gap: calc(7px * var(--ui, 1));
  padding: calc(9px * var(--ui, 1)) calc(8px * var(--ui, 1)) calc(8px * var(--ui, 1)) calc(12px * var(--ui, 1));
  border-bottom: 1px solid var(--line);
}
.sf-pop-head > .sf-ico {
  color: var(--accent);
}
.sf-pop-title {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-weight: 700;
  font-size: calc(12.5px * var(--ui, 1));
}
.sf-pop-scope {
  flex: none;
  padding: 2px calc(7px * var(--ui, 1));
  border-radius: 999px;
  font-size: calc(10px * var(--ui, 1));
  font-weight: 600;
}
.sf-pop-scope.is-report {
  background: var(--accent-soft);
  color: var(--accent);
}
.sf-pop-scope.is-local {
  border: 1px dashed var(--muted);
  color: var(--soft);
}
.sf-icon-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: calc(24px * var(--ui, 1));
  height: calc(24px * var(--ui, 1));
  border-radius: calc(5px * var(--ui, 1));
  color: var(--muted);
}
.sf-icon-btn:hover:not(:disabled) {
  background: var(--hover);
  color: var(--ink);
}
.sf-icon-btn:disabled {
  opacity: 0.35;
  cursor: default;
}
.sf-pop-body {
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  flex-direction: column;
  gap: calc(8px * var(--ui, 1));
  padding: calc(10px * var(--ui, 1)) calc(12px * var(--ui, 1));
  overflow: auto;
}
.sf-input {
  width: 100%;
  height: calc(28px * var(--ui, 1));
  padding: 0 calc(9px * var(--ui, 1));
  border: 1px solid var(--line);
  border-radius: calc(6px * var(--ui, 1));
  background: var(--bg);
  color: var(--ink);
  font: inherit;
  font-size: calc(12px * var(--ui, 1));
  outline: none;
  color-scheme: light;
}
.sf-input:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 calc(3px * var(--ui, 1)) var(--accent-soft);
}
.sf-input::placeholder {
  color: var(--muted);
}
.sf-dark .sf-input {
  color-scheme: dark;
}
.sf-pop-bar {
  display: flex;
  align-items: center;
  gap: calc(10px * var(--ui, 1));
  font-size: calc(11px * var(--ui, 1));
}
.sf-pop-summary {
  flex: 1;
  color: var(--soft);
}
.sf-link-btn {
  color: var(--accent);
  font-size: calc(11px * var(--ui, 1));
  font-weight: 600;
}
.sf-link-btn:hover {
  text-decoration: underline;
}
.sf-list {
  display: flex;
  flex-direction: column;
  min-height: calc(60px * var(--ui, 1));
  max-height: calc(236px * var(--ui, 1));
  overflow: auto;
  margin: 0 calc(-6px * var(--ui, 1));
}
.sf-opt {
  display: flex;
  align-items: center;
  gap: calc(8px * var(--ui, 1));
  min-height: calc(28px * var(--ui, 1));
  padding: calc(3px * var(--ui, 1)) calc(6px * var(--ui, 1));
  border-radius: calc(6px * var(--ui, 1));
  cursor: pointer;
}
.sf-opt:hover {
  background: var(--hover);
}
.sf-opt.is-on {
  background: var(--accent-soft);
}
.sf-opt.is-zero .sf-opt-text {
  color: var(--muted);
}
.sf-opt input {
  flex: none;
  width: calc(14px * var(--ui, 1));
  height: calc(14px * var(--ui, 1));
  margin: 0;
  accent-color: var(--accent);
  cursor: pointer;
}
